+            mutateFirstState(ctx, s1);
+        }
+
+        public void eval(Context ctx, Row s1, Row s2, Row r, Integer mode) {
+            mutateFirstState(ctx, s1);
+            s2.setField("s", String.valueOf(s1.<Integer>getFieldAs("i")));
