+
+        private void mutateFirstState(Context ctx, Row s1) {
+            final Integer i = s1.getFieldAs("i");
+            if (i == null) {
+                ctx.timeContext(Long.class).registerOnTime("end", Long.MAX_VALUE);
+                s1.setField("i", 1);
+            } else {
+                s1.setField("i", i + 1);
+            }
+        }
